  pumpkin_3: () => soil().add(C.leaf, 0.02, grid(3, (x, z, i) => ell(x, 0.11, z, 0.11, 0.02, 0.085, { ry: i * 53, rz: 8 })))
    .add(C.pump, 0, pumpkin(-0.13, 0.2, 0.12, 0.17), pumpkin(0.17, 0.18, -0.1, 0.15), pumpkin(0.14, 0.15, 0.24, 0.1))
