  sugarcane_2: () => soil().add(C.leafL, 0.01, grid(3, (x, z, i) => [cap(x, 0.08, z, x + jit(i, 3) * 0.04, 0.34, z, 0.022), ...leafPair(x, 0.34, z, i, 0.09)])),
  sugarcane_3: () => soil().add(C.cane, 0, grid(3, (x, z, i) => cap(x, 0.08, z, x + jit(i, 3) * 0.05, 0.6 + jit(i, 4) * 0.08, z, 0.026)))
    .add(C.caneD, 0, grid(3, (x, z, i) => [0.24, 0.42].map((h) => tor(x + jit(i, 3) * 0.05 * ((h - 0.08) / 0.52), h, z, 0.026, 0.008))))
